package com.example.hrrepayment.core.i18n

/**
 * English narrative text — generated by `tools/gen_story_en.py` from
 * `staging/i18n/out_story.json` (reviewed translation of the approved Chinese
 * implementation in `core/content/StoryText.kt`).
 *
 * **Do not edit by hand**: edit the translation JSON and re-run the generator, so the
 * Chinese and English structures can never drift apart.
 */
object StoryEn {

    fun eventTitle(id: String): String = when (id) {
        "chapter2_success" -> "Work Evaluation"
        "manager_handover" -> "Personnel Change"
        "overseas_offer" -> "Posting Result"
        "overseas_missed" -> "Posting Result"
        "winter_cold" -> "Physical Condition"
        else -> "Notice"
    }

    fun eventBody(id: String): String = when (id) {
        "chapter2_success" -> "I received the hiring confirmation — this push had gone through. The work evaluation Manager Lin gave me had one more line of approval in it.\n\nI read the notice over again. The school on my résumé is fake; what I got done this time is real."
        "manager_handover" -> "I received a personnel notice: Lin Wei has left, and Zhou Ning is taking over as head of recruiting.\n\nMy salary did not change. But those past “done well”s seemed to have left together with Manager Lin. I have to make the person who receives my results believe me all over again."
        "overseas_offer" -> "I received the posting notice from Manager Zhou: the work assessment, the English, and the department recommendation had all passed, and I was on the assignment list.\n\nThe first thing I opened was my debt page."
        "overseas_missed" -> "I opened the assignment list Manager Zhou forwarded. I was not on it.\n\nThe place went to someone else. I closed the notice; today’s two résumés were still waiting for me."
        "winter_cold" -> "I caught a cold, and my whole body felt heavy. Lines I could normally take in at a glance, today I had to read a second time.\n\nI had meant to finish today’s work as usual."
        else -> ""
    }

    fun endingTitle(id: String?): String = when (id) {
        "overseas_repaid" -> "Across the Ocean · A Life Turned Around"
        "debt_free_restart" -> "Light as Air · A Bitter Restart"
        "overseas_indebted" -> "Gone Without a Trace · Above the Law"
        "bankruptcy" -> "The Snowballing Abyss · The Gambler’s Last Road"
        "indebted_layoff" -> "One Speck of the Times · Stuck at the Bottom"
        "health_death" -> "Time Out of Joint · Dust of an Era"
        "low_dopamine" -> "One Lousy Life"
        "exposed" -> "Caught Out"
        else -> "Game Over"
    }

    fun endingBody(id: String?, reason: String?): String = when (id) {
            "overseas_repaid" -> {
            "The debt is zero. I checked it once more; I no longer have to set aside an amount from next month’s salary for the past.\n\nWhat first got me in the door was a fake degree. Now the materials I have reviewed, the English I have learned, and the work I have done have finally given me a little solid footing.\n\nLater, I completed the project handover and the posting preparations as the notice required. The year-end itinerary was settled, and I would set off at the start of the year. Before leaving, I read the settled bills through once more, and only then closed that page.\n\nThat entry in my onboarding file is still not true. I don’t know when it will be opened again, but at least this time I have a life I can start without borrowing money."
            }
            "debt_free_restart" -> {
            if (reason == "trust_negative" || reason == "exposed_debt_zero") {
                "I received the conclusion of the onboarding materials review. That overseas degree had failed verification, and the company notified me that my employment was terminated.\n\nEvery day I judged other people’s materials; this time it was my turn. The work I have done has not disappeared, but it cannot testify for that fake certificate.\n\nI looked at the bill again. The debt was already settled — these days did not leave nothing behind.\n\nI started a new résumé and deleted that school from it. Writing from my own real experience is slower than I expected. Whether I will be chosen next time, I don’t know."
            } else {
                "I checked the last bill. The debt is zero; next year’s salary can finally be left for next year’s life.\n\nI began to think about whether my next résumé, my own, should have that school I never attended deleted from it.\n\nLater, news of the pandemic filled the screen.\n\nThat day came, and every plan disappeared.\n\nI received notice of layoff negotiations. The executive recruiting, the internal arguments, and all that dirty work of writing non-compliant materials up as “no problem” — one by one they were dug out again. I did not do as I was told, and I could not hold my place in those arguments either. The termination notice arrived in the end.\n\nI opened my own résumé again. This time I deleted that school and kept the work I had actually done. There is still no interview lined up, but at least the debt column no longer has to follow me."
            }
            }
            "overseas_indebted" -> {
            "The debt is still there. The posting notice never asked about it, and I did not bring it up.\n\nLater, I left under the assignment arrangement and stopped using the contact numbers I usually used at home. Work correspondence stayed in the company system; the rest of my messages I left on another number.\n\nThat road was not clean, but at least it kept me from seeing the collection notices every day. I called that quiet a fresh start.\n\nBut I never received a single proof of settlement. Along with that fake degree, I had only set the old business down somewhere no one was asking about for now."
            }
            "bankruptcy" -> {
            if (reason == "cash_exhausted") {
                "I refreshed the balance again and again; the number did not change. The money available to me was gone, and the debt was still there.\n\nI had been arranging the days in front of me around the next payment coming in, as if I could keep going as long as I could work out the next step.\n\nNow the money for the next step was gone too. Today’s bill would not count as already paid just because I was still waiting for money.\n\nThe future dates were still listed on the screen. I stopped here."
            } else {
                "The interest for the year was entered into the bill. I went over the repayment record; the debt had still crossed six hundred thousand.\n\nThat was the amount I had owed when I started. I once thought that as long as the salary came in payment after payment, this number would only get smaller.\n\nI paged back through the bills, trying to find which step had gone wrong. The interest was already entered; turning back to any page could not change the result for this period.\n\nI was back outside that starting point again."
            }
            }
            "indebted_layoff" -> {
            "The accounts for the last year were settled; the debt was not yet cleared. I put next year’s salary into the plan, thinking that if I held on a while longer, I might be able to make up this stretch.\n\nLater, news of the pandemic filled the screen.\n\nThat day came, and every plan disappeared.\n\nThe layoff notice arrived. I looked at the date first, then worked out how far my salary could still be counted. The most certain line in the plan had gone blank too.\n\nI started sending my résumé out. Before, I picked one out of two people; now I wait for someone to pick me out of a pile.\n\nEvery time a notification lit up, I thought first that it was an interview message. Sometimes it was only a bill. The debt is still there, and I still have to keep looking for work."
            }
            "health_death" -> {
            if (reason == "cold_health_low") {
                "I wanted to finish reading the first résumé; my finger stopped halfway down the page. The words crowded together, and I started again from the line above.\n\nI lowered the phone a little, thinking I would rest a moment and then go on. Today’s date was still lit; the work was not finished yet.\n\nThe rest of the words, I did not finish reading."
            } else {
                "I finished checking the year-end accounts and wanted to put the phone down. The motion was strangely slow.\n\nI always put rest after work and bills, thinking that once these things were dealt with, time would open up.\n\nThe date on the screen stopped on the last day of December. I wanted to see it a little more clearly, but the words in front of me kept drawing further away."
            }
            }
            "low_dopamine" -> {
            "For a long time now, I have finished the same few things every day, and I cannot think of anything I still want once they are done.\n\nI cursed myself as “a lousy life.” Cursing did not make it any better. Even explaining where it hurt felt like too much effort.\n\nThat night, I had the thought of ending my own life. I did not tell anyone about it; what was left on the screen was still those work reminders.\n\nThe last notification lit up. I did not open it again."
            }
            "exposed" -> {
            "I received the conclusion of the onboarding materials review. That overseas degree had failed verification, and the company notified me that my employment was terminated.\n\nThis time there were no two sets of materials to compare, and no other name to push it onto. What I was asked to explain was my own column.\n\nI had prepared many ways of saying it. After the conclusion came, not one of those words was of any use.\n\nThe debt is still there, but my next salary can no longer be worked out at the same figure. I closed the company notice and opened my own résumé again."
            }
            else -> "I stopped here."
    }
}
